@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
    </div>
}
else if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    var filtered = FilteredTasks;
    var toDo = filtered.Where(t => t.Status == "To Do").ToList();
    var inProgress = filtered.Where(t => t.Status == "In Progress").ToList();
    var done = filtered.Where(t => t.Status == "Done").ToList();
    var overdue = _tasks!.Count(t => t.DueDate.Date < DateTime.Today);

    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">@_tasks!.Count</div>
                    <small class="text-muted">Total</small>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">@_tasks!.Count(t => t.Status == "To Do")</div>
                    <small class="text-muted">To Do</small>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">@_tasks!.Count(t => t.Status == "In Progress")</div>
                    <small class="text-muted">In Progress</small>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">@_tasks!.Count(t => t.Status == "Done")</div>
                    <small class="text-muted">Done</small>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold text-danger">@overdue</div>
                    <small class="text-muted">Overdue</small>
                </div>
            </div>
        </div>
    </div>

    <!-- Search bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @{ RenderColumn("To Do", toDo, null, "In Progress"); }
        @{ RenderColumn("In Progress", inProgress, "To Do", "Done"); }
        @{ RenderColumn("Done", done, "In Progress", null); }
    </div>
}

@code {
    private List<TaskItem>? _tasks;
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Track which column has the add-task form open
    private string? _addingInColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today;

    private List<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(_searchText)
            ? _tasks!
            : _tasks!.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void RenderColumn(string status, List<TaskItem> tasks, string? leftStatus, string? rightStatus)
    {
        <div class="col-md-4">
            <div class="card">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@status</strong>
                    <span class="badge bg-secondary">@tasks.Count</span>
                </div>
                <div class="card-body d-flex flex-column gap-2" style="min-height:200px;">
                    @foreach (var task in tasks)
                    {
                        var currentTask = task;
                        <div class="card">
                            <div class="card-body p-2">
                                <div class="fw-semibold">@currentTask.Title</div>
                                <small class="text-muted">@currentTask.Assignee</small>
                                <div class="d-flex justify-content-between align-items-center mt-1">
                                    <span class="badge @PriorityClass(currentTask.Priority)">@currentTask.Priority</span>
                                    <small>@currentTask.DueDate.ToString("MMM dd")</small>
                                </div>
                                <div class="d-flex justify-content-end gap-1 mt-2">
                                    @if (leftStatus is not null)
                                    {
                                        var left = leftStatus;
                                        <button class="btn btn-outline-secondary btn-sm"
                                                @onclick="() => MoveTask(currentTask.Id, left)">
                                            ◀ Move Left
                                        </button>
                                    }
                                    @if (rightStatus is not null)
                                    {
                                        var right = rightStatus;
                                        <button class="btn btn-outline-secondary btn-sm"
                                                @onclick="() => MoveTask(currentTask.Id, right)">
                                            Move Right ▶
                                        </button>
                                    }
                                </div>
                            </div>
                        </div>
                    }

                    @if (_addingInColumn == status)
                    {
                        <div class="card border-primary">
                            <div class="card-body p-2">
                                <div class="mb-2">
                                    <input type="text" class="form-control form-control-sm" placeholder="Title"
                                           @bind="_newTitle" />
                                </div>
                                <div class="mb-2">
                                    <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                           @bind="_newAssignee" />
                                </div>
                                <div class="mb-2">
                                    <select class="form-select form-select-sm" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                </div>
                                <div class="mb-2">
                                    <input type="date" class="form-control form-control-sm" @bind="_newDueDate" />
                                </div>
                                <div class="d-flex gap-1">
                                    <button class="btn btn-primary btn-sm" @onclick="() => SaveNewTask(status)">Save</button>
                                    <button class="btn btn-secondary btn-sm" @onclick="CancelAdd">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                </div>
                <div class="card-footer">
                    <button class="btn btn-outline-primary btn-sm w-100"
                            @onclick="() => ShowAddForm(status)">
                        + Add Task
                    </button>
                </div>
            </div>
        </div>
    }

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _tasks!.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                var old = _tasks[idx];
                _tasks[idx] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private void ShowAddForm(string column)
    {
        _addingInColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today;
    }

    private void CancelAdd()
    {
        _addingInColumn = null;
    }

    private async Task SaveNewTask(string status)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
            // The service creates tasks — if it doesn't assign the column status, fix it up locally
            var final = created.Status == status ? created : created with { Status = status };
            _tasks!.Add(final);
            _addingInColumn = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

